    terms = []
    for i, coeff in enumerate(coeffs):
        if coeff != 0:
            term = ""
            if coeff < 0:
                term += "-"
            elif len(terms) > 0:
                term += "+"
            if abs(coeff) != 1 or i == n:
                term += str(abs(coeff))
            if i > 0:
                term += "x"
            if i > 1:
                term += "^" + str(i)
            terms.append(term)
    return "".join(terms)

