def select_volunteers(n, m, applicants):
    # Sort applicants based on test score in descending order
    applicants = sorted(applicants, key=lambda x: x[1], reverse=True)

    # Calculate interview score cutoff as 150% of planned number of recruits rounded down
    cutoff = int(n * 1.5)

    # Create a list to store qualified applicants
    qualified = []

    # Loop through applicants and add qualified ones to list
    for app in applicants:
        if app[1] >= cutoff:
            qualified.append(app)

    # Return interview score cutoff and list of qualified applicants
    return (cutoff, qualified)

