def preorder_traversal(inorder, postorder):
    if inorder == '' and postorder == '':
        return ''
    root = postorder[-1]
    idx = inorder.index(root)
    left = inorder[:idx]
    right = inorder[idx+1:]
    left_post = postorder[:len(left)]
    right_post = postorder[len(left):-1]
    return root + preorder_traversal(left, left_post) + preorder_traversal(right, right_post)

